-- c010-v002: – lakini anayeingia kupitia – mlango mchungaji ni wa– kondoo
-- c010-v003: huyu – mlinzi–wa–mlango anamfungulia na – kondoo – sauti yake wanasikia na – wake kondoo anawaita kwa jina na anawatoa–nje wao
-- c010-v004: wakati – wake wote anawatoa–nje mbele yao anatangulia na – kondoo yeye wanamfuata kwa–sababu wanaijua – sauti yake
