-- c010-v006: Huu – mfano aliwaambia wao – Iēsoûs wale lakini hawakujua walijua ni–nini yalikuwa ambayo aliwaambia wao
-- c010-v007: Akawaambia basi tena wao – Iēsoûs Amēn amēn ninawaambia ninyi kwamba mimi ndimi – mlango wa– kondoo
-- c010-v008: wote wengi walikuja kabla–yangu mimi wezi ni na wanyang'anyi lakini hawaku wasikia wao – kondoo
-- c010-v009: mimi ndimi – mlango kupitia mimi kama mtu–yeyote ataingia ataokolewa na ataingia na atatoka na malisho atapata
-- c010-v010: – mwizi haji anakuja isipokuwa si ili aibe na achinje na aangamize mimi nilikuja ili uzima wawe–na na kwa–wingi wawe–na
-- c010-v011: mimi ndimi – mchungaji – mwema – mchungaji – mwema – uhai wake anatoa kwa–ajili–ya – kondoo
-- c010-v012: – mtu–wa–mshahara na asiye kuwa mchungaji ambaye si ni – kondoo wake anaona – mbwa–mwitu akija na anawaacha – kondoo na anakimbia na – mbwa–mwitu anawanyakua wao na anawatawanya
-- c010-v013: kwa–sababu mtu–wa–mshahara ni na ha jali yeye kuhusu – kondoo
-- c010-v014: mimi ndimi – mchungaji – mwema na ninawajua – wangu na wananijua mimi – wangu
-- c010-v015: kama–vile ananijua mimi – Baba na–mimi ninamjua – Baba na – uhai wangu ninatoa kwa–ajili–ya – kondoo
-- c010-v016: na wengine kondoo ninao ambao si ni kutoka – zizi hili na–wale ni–lazima mimi niwalete na – sauti yangu watasikia na watakuwa kundi–moja kundi mchungaji–mmoja mchungaji
-- c010-v017: kwa–hiyo hili mimi – Baba ananipenda kwa–sababu mimi ninatoa – uhai wangu ili tena niupokee yeye
-- c010-v018: hakuna–mtu anauondoa yeye kutoka kwangu bali mimi ninautoa yeye kutoka mwenyewe mamlaka nina kuutoa yeye na mamlaka nina tena kuupokea yeye hii – amri nilipokea kutoka–kwa – Baba yangu
-- c010-v019: Mgawanyiko tena ukawa kati–ya – Wayahudi kwa–sababu–ya – maneno haya
-- c010-v020: wakasema na wengi kati yao Pepo ana na ana–wazimu kwa–nini yeye mnamsikia
-- c010-v021: wengine walisema Haya – maneno si ni ya–mtu–mwenye–pepo je pepo anaweza vipofu macho kufungua
-- c010-v022: Ikawa wakati–huo – Kumbukumbu katika – Yerusalemu baridi ilikuwa
-- c010-v023: na alitembea – Iēsoûs katika – hekalu katika – ukumbi wa– Solomōn
-- c010-v024: walimzunguka basi yeye – Wayahudi na wakamwambia yeye Hadi lini – nafsi yetu unaiondoa kama wewe ndiye – Christós tuambie sisi wazi
-- c010-v025: aliwajibu wao – Iēsoûs Nimewaambia ninyi na hamwamini mwaamini – kazi ambazo mimi ninafanya katika – jina la– Baba yangu hizi zinashuhudia kuhusu mimi
-- c010-v026: lakini ninyi hamwamini mwaamini kwa–sababu hamko mko kati–ya – kondoo – wangu
-- c010-v027: – kondoo – wangu – sauti yangu wanasikia na–mimi ninawajua wao na wananifuata mimi
