-- c010-v035: kama wale aliwaita miungu ambao kwao – neno la– Mungu lilikuja na haiwezi inaweza kuvunjwa – maandiko
-- c010-v036: ambaye – Baba alimtakasa na akamtuma katika – ulimwengu ninyi mnasema kwamba Unakufuru kwa–sababu nilisema Mwana wa– Mungu ndimi
-- c010-v037: kama si ninafanya – kazi za– Baba yangu msi niamini mimi
